// Find the point with the lowest y-coordinate (and leftmost if tie)
auto bottom_left = points.begin();
for (auto it = points.begin() + 1; it != points.end(); ++it) {
    if (it->y() < bottom_left->y() || (it->y() == bottom_left->y() && it->x() < bottom_left->x())) {
        bottom_left = it;
    }
}

// Move the bottom-left point to the front
std::swap(points[0], *bottom_left);

// Sort points by polar angle with respect to bottom-left point
std::sort(points.begin() + 1, points.end(), [&](const Point_2& a, const Point_2& b) {
    // Compute cross product of vectors (bottom_left->a) and (bottom_left->b)
    auto cross = (a.x() - points[0].x()) * (b.y() - points[0].y()) - (b.x() - points[0].x()) * (a.y() - points[0].y());
    if (cross != 0) return cross > 0;
    // If collinear, sort by distance (closer first)
    auto dist_a = (a.x() - points[0].x()) * (a.x() - points[0].x()) + (a.y() - points[0].y()) * (a.y() - points[0].y());
    auto dist_b = (b.x() - points[0].x()) * (b.x() - points[0].x()) + (b.y() - points[0].y()) * (b.y() - points[0].y());
    return dist_a < dist_b;
});

// Remove collinear points (keep only the farthest)
auto last = points.begin() + 1;
for (auto it = points.begin() + 2; it != points.end(); ++it) {
    if ((it->x() - points[0].x()) * (last->y() - points[0].y()) != (it->y() - points[0].y()) * (last->x() - points[0].x())) {
        ++last;
        *last = *it;
    }
}
points.erase(last + 1, points.end());

// Graham scan
std::vector<Point_2> hull;
hull.reserve(points.size());
hull.push_back(points[0]);
hull.push_back(points[1]);

for (size_t i = 2; i < points.size(); ++i) {
    while (hull.size() >= 2) {
        const Point_2& p1 = hull[hull.size() - 2];
        const Point_2& p2 = hull[hull.size() - 1];
        const Point_2& p3 = points[i];

        // Cross product of (p1->p2) and (p2->p3)
        double cross = (p2.x() - p1.x()) * (p3.y() - p2.y()) - (p2.y() - p1.y()) * (p3.x() - p2.x());
        if (cross > 0) break; // left turn
        hull.pop_back(); // right turn or collinear, remove p2
    }
    hull.push_back(points[i]);
}

// Ensure CCW order: if the last point is collinear with first two, remove it
if (hull.size() > 2) {
    const Point_2& p1 = hull[0];
    const Point_2& p2 = hull[1];
    const Point_2& p3 = hull.back();
    double cross = (p2.x() - p1.x()) * (p3.y() - p2.y()) - (p2.y() - p1.y()) * (p3.x() - p2.x());
    if (cross == 0) {
        hull.pop_back();
    }
}

return hull;

